        $out->{'while'} = $this->toWhile();
        $out->{'willSet'} = $this->toWillSet();
        $out->{'with'} = $this->toWith();
        $out->{'xor'} = $this->toXor();
        $out->{'xor_eq'} = $this->toXorEq();
        $out->{'YES'} = $this->toYes();
        $out->{'yield'} = $this->toYield();
        return $out;
    }

